"""Deterministic media fixtures generated by FFmpeg at test time.

Every file here is produced by a command, not committed as a binary, so the suite stays
small and the fixture is exactly reproducible. Everything is a couple of seconds long and a
few hundred kilobytes at most: enough to exercise real decoding, far too small to slow a
run down.
"""
from __future__ import annotations

import subprocess
from dataclasses import dataclass
from pathlib import Path

import pytest

from creatoros.core.settings import get_settings


def ffmpeg_exe() -> Path:
    return get_settings().ffmpeg_bin / "ffmpeg.exe"


def ffprobe_exe() -> Path:
    return get_settings().ffmpeg_bin / "ffprobe.exe"


def run_ffmpeg(args: list[str], *, timeout: int = 120) -> None:
    completed = subprocess.run(
        [str(ffmpeg_exe()), "-hide_banner", "-loglevel", "error", "-y", *args],
        capture_output=True,
        timeout=timeout,
        check=False,
        creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
    )
    if completed.returncode != 0:  # pragma: no cover - fixture setup failure
        raise RuntimeError(
            f"fixture generation failed ({completed.returncode}): "
            f"{completed.stderr.decode('utf-8', 'replace')[:400]}"
        )


@dataclass(slots=True)
class MediaFixtures:
    directory: Path

    @property
    def landscape(self) -> Path:
        return self.directory / "landscape.mp4"

    @property
    def portrait(self) -> Path:
        return self.directory / "portrait.mp4"

    @property
    def silent(self) -> Path:
        return self.directory / "silent.mp4"

    @property
    def image(self) -> Path:
        return self.directory / "still.jpg"

    @property
    def image_png(self) -> Path:
        return self.directory / "still.png"

    @property
    def audio(self) -> Path:
        return self.directory / "tone.mp3"

    @property
    def audio_wav(self) -> Path:
        return self.directory / "tone.wav"

    @property
    def silence(self) -> Path:
        return self.directory / "silence.wav"

    @property
    def fake(self) -> Path:
        return self.directory / "fake.mp4"

    @property
    def truncated(self) -> Path:
        return self.directory / "truncated.mp4"

    @property
    def big(self) -> Path:
        return self.directory / "wide_4k.mp4"


@pytest.fixture(scope="session")
def media_files(tmp_path_factory) -> MediaFixtures:
    if not ffmpeg_exe().exists():  # pragma: no cover - only on a broken install
        pytest.skip("ffmpeg is not installed; media tests need it")

    directory = tmp_path_factory.mktemp("media-fixtures")
    fixtures = MediaFixtures(directory)

    run_ffmpeg(
        [
            "-f", "lavfi", "-i", "testsrc2=size=640x360:rate=25:duration=2",
            "-f", "lavfi", "-i", "sine=frequency=440:duration=2",
            "-c:v", "libx264", "-preset", "ultrafast", "-crf", "30", "-pix_fmt", "yuv420p",
            "-c:a", "aac", "-b:a", "64k", "-shortest",
            str(fixtures.landscape),
        ]
    )
    run_ffmpeg(
        [
            "-f", "lavfi", "-i", "testsrc2=size=360x640:rate=24:duration=2",
            "-f", "lavfi", "-i", "sine=frequency=330:duration=2",
            "-c:v", "libx264", "-preset", "ultrafast", "-crf", "30", "-pix_fmt", "yuv420p",
            "-c:a", "aac", "-b:a", "64k", "-shortest",
            str(fixtures.portrait),
        ]
    )
    run_ffmpeg(
        [
            "-f", "lavfi", "-i", "testsrc2=size=320x240:rate=15:duration=1",
            "-c:v", "libx264", "-preset", "ultrafast", "-crf", "32", "-pix_fmt", "yuv420p",
            "-an",
            str(fixtures.silent),
        ]
    )
    run_ffmpeg(["-f", "lavfi", "-i", "testsrc2=size=800x600:duration=1", "-frames:v", "1", str(fixtures.image)])
    run_ffmpeg(["-f", "lavfi", "-i", "testsrc2=size=640x480:duration=1", "-frames:v", "1", str(fixtures.image_png)])
    run_ffmpeg(
        ["-f", "lavfi", "-i", "sine=frequency=440:duration=2", "-c:a", "libmp3lame", "-b:a", "96k", str(fixtures.audio)]
    )
    run_ffmpeg(["-f", "lavfi", "-i", "sine=frequency=440:duration=1", "-c:a", "pcm_s16le", str(fixtures.audio_wav)])
    run_ffmpeg(["-f", "lavfi", "-i", "anullsrc=r=8000:cl=mono", "-t", "1", "-c:a", "pcm_s16le", str(fixtures.silence)])
    run_ffmpeg(
        [
            "-f", "lavfi", "-i", "testsrc2=size=1280x720:rate=20:duration=1",
            "-c:v", "libx264", "-preset", "ultrafast", "-crf", "34", str(fixtures.big),
        ]
    )

    fixtures.fake.write_bytes(b"this is a text file pretending to be a video")
    data = fixtures.landscape.read_bytes()
    fixtures.truncated.write_bytes(data[: max(2000, len(data) // 6)])
    return fixtures


@pytest.fixture()
def library(session):
    from creatoros.services.media.library import MediaLibrary

    return MediaLibrary(session)
